\draw[thick] (0,2.7)--++(0.12,0.18)--++(-0.24,0)--++(0.12,-0.18);
\fill (0,2.78) circle (0.05);
\node[right] at (0.25,2.85) {Pole Star};
% other stars trails
\draw[->,thick] (-2.2,1.6) arc (200:320:1.15);
\draw[->,thick] (2.2,1.6) arc (-20:100:1.15);
\node[font=\footnotesize] at (-2.5,0.6) {star trail};
